exercises.solution:
package main

import "fmt"

// Grade переводит баллы в оценку A–F.
func Grade(score int) string {
	switch {
	case score >= 90:
		return "A"
	case score >= 80:
		return "B"
	case score >= 70:
		return "C"
	case score >= 60:
		return "D"
	default:
		return "F"
	}
}

func main() {
	fmt.Println(Grade(95), Grade(72), Grade(41))
}

