exercises.solution:
package main

import "fmt"

// MinMax возвращает минимум и максимум среза nums.
func MinMax(nums []int) (int, int) {
	if len(nums) == 0 {
		return 0, 0
	}
	low, high := nums[0], nums[0]
	for _, value := range nums[1:] {
		if value < low {
			low = value
		}
		if value > high {
			high = value
		}
	}
	return low, high
}

func main() {
	fmt.Println(MinMax([]int{3, 1, 4}))
}

