package main

import (
	"fmt"
	"strings"
)

// CountVowels считает гласные латинские буквы в строке.
func CountVowels(s string) int {
	count := 0
	for _, char := range strings.ToLower(s) {
		switch char {
		case 'a', 'e', 'i', 'o', 'u':
			count++
		}
	}
	return count
}

