exercises.solution:
package main

import "fmt"

// Unique убирает повторы, сохраняя порядок первого появления.
func Unique(words []string) []string {
	seen := make(map[string]bool, len(words))
	result := make([]string, 0, len(words))
	for _, word := range words {
		if seen[word] {
			continue
		}
		seen[word] = true
		result = append(result, word)
	}
	return result
}

func main() {
	fmt.Println(Unique([]string{"go", "ру", "go", "sql"}))
}

exercises.tests:
package main

import (
	"reflect"
	"testing"
)

// TestUniqueKeepsOrder удаляет повторы и сохраняет порядок.
func TestUniqueKeepsOrder(t *testing.T) {
	got := Unique([]string{"go", "ру", "go", "sql", "ру"})
	want := []string{"go", "ру", "sql"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Unique = %v, ожидалось %v", got, want)
	}
}

// TestUniqueEmpty возвращает пустой результат.
func TestUniqueEmpty(t *testing.T) {
	if got := Unique(nil); len(got) != 0 {
		t.Fatalf("Unique(nil) = %v, ожидалось пусто", got)
	}
}

