exercises.solution:
package main

import (
	"fmt"
	"strings"
)

// WordCount считает частоты слов без учёта регистра.
func WordCount(text string) map[string]int {
	cleaned := strings.Map(func(char rune) rune {
		switch char {
		case ',', '.', '!', '?', ';', ':', '"', '\'':
			return ' '
		}
		return char
	}, strings.ToLower(text))

	counts := make(map[string]int)
	for _, word := range strings.Fields(cleaned) {
		counts[word]++
	}
	return counts
}

func main() {
	fmt.Println(WordCount("Go go, SQL"))
}

