package main

import (
	"fmt"
	"unicode"
)

// IsPalindrome проверяет, читается ли строка одинаково в обе стороны.
func IsPalindrome(s string) bool {
	cleaned := make([]rune, 0, len(s))
	for _, char := range s {
		if unicode.IsLetter(char) || unicode.IsDigit(char) {
			cleaned = append(cleaned, unicode.ToLower(char))
		}
	}
	for left, right := 0, len(cleaned)-1; left < right; left, right = left+1, right-1 {
		if cleaned[left] != cleaned[right] {
			return false
		}
	}
	return true
}

func main() {
	fmt.Println(IsPalindrome("А роза упала на лапу Азора"))
}

