package main

import (
	"errors"
	"fmt"
)

// ErrInsufficientFunds возвращается при попытке снять больше, чем есть.
var ErrInsufficientFunds = errors.New("недостаточно средств")

// Account — банковский счёт.
type Account struct {
	balance int
}

// NewAccount создаёт счёт с начальным балансом.
func NewAccount(initial int) *Account {
	return &Account{balance: initial}
}

// Deposit пополняет счёт.
func (a *Account) Deposit(amount int) {
	a.balance += amount
}

// Withdraw снимает деньги, если их достаточно.
func (a *Account) Withdraw(amount int) error {
	if amount > a.balance {
		return ErrInsufficientFunds
	}
	a.balance -= amount
	return nil
}

// Balance возвращает текущий баланс.
func (a *Account) Balance() int {
	return a.balance
}

func main() {
	account := NewAccount(100)
	account.Deposit(50)
	fmt.Println(account.Balance())
}

