exercises.solution:
package main

import (
	"errors"
	"fmt"
)

// ErrEmptyStack возвращается при обращении к пустому стеку.
var ErrEmptyStack = errors.New("стек пуст")

// Stack — стек целых чисел.
type Stack struct {
	items []int
}

// Push кладёт значение на вершину стека.
func (s *Stack) Push(value int) {
	s.items = append(s.items, value)
}

// Pop снимает верхний элемент.
func (s *Stack) Pop() (int, error) {
	if len(s.items) == 0 {
		return 0, ErrEmptyStack
	}
	last := len(s.items) - 1
	value := s.items[last]
	s.items = s.items[:last]
	return value, nil
}

// Peek смотрит на верхний элемент, не снимая его.
func (s *Stack) Peek() (int, error) {
	if len(s.items) == 0 {
		return 0, ErrEmptyStack
	}
	return s.items[len(s.items)-1], nil
}

// Len возвращает количество элементов.
func (s *Stack) Len() int {
	return len(s.items)
}

func main() {
	var stack Stack
	stack.Push(1)
	value, _ := stack.Pop()
	fmt.Println(value)
}

