package main

import (
	"fmt"
	"math"
)

// Shape — фигура с площадью.
type Shape interface {
	Area() float64
}

// Rect — прямоугольник.
type Rect struct {
	W, H float64
}

// Area возвращает площадь прямоугольника.
func (r Rect) Area() float64 {
	return r.W * r.H
}

// Circle — круг.
type Circle struct {
	R float64
}

// Area возвращает площадь круга.
func (c Circle) Area() float64 {
	return math.Pi * c.R * c.R
}

// TotalArea складывает площади фигур.
func TotalArea(shapes []Shape) float64 {
	total := 0.0
	for _, shape := range shapes {
		total += shape.Area()
	}
	return total
}

func main() {
	fmt.Println(TotalArea([]Shape{Rect{W: 2, H: 3}, Circle{R: 1}}))
}

