package main

import (
	"errors"
	"fmt"
)

// ErrNotFound — общая причина: пользователя нет.
var ErrNotFound = errors.New("пользователь не найден")

// NotFoundError уточняет, какого пользователя не хватило.
type NotFoundError struct {
	ID int
}

// Error реализует интерфейс error.
func (e *NotFoundError) Error() string {
	return fmt.Sprintf("пользователь %d не найден", e.ID)
}

// Unwrap связывает ошибку с ErrNotFound.
func (e *NotFoundError) Unwrap() error {
	return ErrNotFound
}

// User — пользователь.
type User struct {
	ID   int
	Name string
}

// LoadUser возвращает пользователя или обёрнутую ошибку.
func LoadUser(id int) (User, error) {
	if id <= 0 {
		return User{}, fmt.Errorf("загрузить пользователя: %w", &NotFoundError{ID: id})
	}
	return User{ID: id, Name: fmt.Sprintf("user-%d", id)}, nil
}

func main() {
	user, err := LoadUser(0)
	fmt.Println(user, err)
}

