package main

import (
	"encoding/json"
	"fmt"
)

// User — пользователь сервиса.
type User struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email,omitempty"`
}

// MarshalUser сериализует пользователя в JSON.
func MarshalUser(user User) (string, error) {
	raw, err := json.Marshal(user)
	if err != nil {
		return "", err
	}
	return string(raw), nil
}

// ParseUser разбирает пользователя из JSON.
func ParseUser(data string) (User, error) {
	var user User
	if err := json.Unmarshal([]byte(data), &user); err != nil {
		return User{}, err
	}
	return user, nil
}

func main() {
	data, _ := MarshalUser(User{ID: 1, Name: "Аня"})
	fmt.Println(data)
}

