package main

import (
	"fmt"
	"sync"
)

// Counter — потокобезопасный счётчик.
type Counter struct {
	mu    sync.Mutex
	value int
}

// Inc увеличивает счётчик на единицу.
func (c *Counter) Inc() {
	c.Add(1)
}

// Add увеличивает счётчик на delta.
func (c *Counter) Add(delta int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.value += delta
}

// Value возвращает текущее значение.
func (c *Counter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.value
}

func main() {
	var counter Counter
	counter.Inc()
	fmt.Println(counter.Value())
}

