exercises.solution:
package main

import (
	"fmt"
	"sync"
)

// SumWorkers складывает числа, распределив работу между воркерами.
func SumWorkers(nums []int, workers int) int {
	if len(nums) == 0 {
		return 0
	}
	if workers < 1 {
		workers = 1
	}
	if workers > len(nums) {
		workers = len(nums)
	}

	jobs := make(chan int)
	results := make(chan int, workers)

	var wait sync.WaitGroup
	wait.Add(workers)
	for worker := 0; worker < workers; worker++ {
		go func() {
			defer wait.Done()
			partial := 0
			for index := range jobs {
				partial += nums[index]
			}
			results <- partial
		}()
	}

	go func() {
		for index := range nums {
			jobs <- index
		}
		close(jobs)
	}()

	go func() {
		wait.Wait()
		close(results)
	}()

	total := 0
	for partial := range results {
		total += partial
	}
	return total
}

func main() {
	fmt.Println(SumWorkers([]int{1, 2, 3, 4, 5}, 3))
}

