exercises.solution:
package main

import "fmt"

// LRU — кэш с вытеснением давно использованных записей.
type LRU struct {
	capacity int
	values   map[string]int
	order    []string
}

// NewLRU создаёт кэш заданной ёмкости.
func NewLRU(capacity int) *LRU {
	if capacity < 1 {
		capacity = 1
	}
	return &LRU{capacity: capacity, values: make(map[string]int, capacity)}
}

// touch перемещает ключ в конец order: он становится самым свежим.
func (c *LRU) touch(key string) {
	for index, existing := range c.order {
		if existing == key {
			c.order = append(c.order[:index], c.order[index+1:]...)
			break
		}
	}
	c.order = append(c.order, key)
}

// Get возвращает значение и признак наличия.
func (c *LRU) Get(key string) (int, bool) {
	value, ok := c.values[key]
	if !ok {
		return 0, false
	}
	c.touch(key)
	return value, true
}

// Put добавляет или обновляет значение.
func (c *LRU) Put(key string, value int) {
	if _, exists := c.values[key]; exists {
		c.values[key] = value
		c.touch(key)
		return
	}
	if len(c.values) >= c.capacity {
		oldest := c.order[0]
		c.order = c.order[1:]
		delete(c.values, oldest)
	}
	c.values[key] = value
	c.order = append(c.order, key)
}

// Len возвращает количество записей.
func (c *LRU) Len() int {
	return len(c.values)
}

func main() {
	cache := NewLRU(2)
	cache.Put("a", 1)
	value, _ := cache.Get("a")
	fmt.Println(value)
}

