package main

import "testing"

// TestLRUEvictsOldest вытесняет самую давнюю запись.
func TestLRUEvictsOldest(t *testing.T) {
	cache := NewLRU(2)
	cache.Put("a", 1)
	cache.Put("b", 2)
	cache.Put("c", 3)

	if _, ok := cache.Get("a"); ok {
		t.Fatal("a должна быть вытеснена")
	}
	if value, ok := cache.Get("b"); !ok || value != 2 {
		t.Fatalf("b = (%d, %v)", value, ok)
	}
	if cache.Len() != 2 {
		t.Fatalf("Len = %d, ожидалось 2", cache.Len())
	}
}

// TestLRUGetRefreshesOrder обновляет порядок при чтении.
func TestLRUGetRefreshesOrder(t *testing.T) {
	cache := NewLRU(2)
	cache.Put("a", 1)
	cache.Put("b", 2)
	cache.Get("a")   // a становится свежей
	cache.Put("c", 3) // теперь должна вытесниться b

	if _, ok := cache.Get("b"); ok {
		t.Fatal("b должна быть вытеснена после Get(\"a\")")
	}
	if value, ok := cache.Get("a"); !ok || value != 1 {
		t.Fatalf("a = (%d, %v)", value, ok)
	}
}

