package main

import (
	"errors"
	"fmt"
	"strings"
)

// Причины ошибок валидации.
var (
	ErrInvalidAge   = errors.New("некорректный возраст")
	ErrInvalidEmail = errors.New("некорректный email")
)

// FieldError привязывает ошибку к полю формы.
type FieldError struct {
	Field string
	Err   error
}

// Error реализует интерфейс error.
func (e *FieldError) Error() string {
	return e.Field + ": " + e.Err.Error()
}

// Unwrap возвращает исходную причину.
func (e *FieldError) Unwrap() error {
	return e.Err
}

// Validate проверяет возраст и email.
func Validate(age int, email string) error {
	var problems []error
	if age < 0 || age > 150 {
		problems = append(problems, &FieldError{Field: "age", Err: ErrInvalidAge})
	}
	if !strings.Contains(email, "@") {
		problems = append(problems, &FieldError{Field: "email", Err: ErrInvalidEmail})
	}
	return errors.Join(problems...)
}

func main() {
	fmt.Println(Validate(-1, "нет-собаки"))
}

