exercises.solution:
package main

import (
	"encoding/csv"
	"fmt"
	"strconv"
	"strings"
)

// Record — одна строка с данными.
type Record struct {
	Name  string
	Score int
}

// ParseCSV разбирает CSV с заголовком name,score.
func ParseCSV(data string) ([]Record, error) {
	reader := csv.NewReader(strings.NewReader(data))
	reader.FieldsPerRecord = -1
	rows, err := reader.ReadAll()
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return []Record{}, nil
	}

	records := make([]Record, 0, len(rows)-1)
	for index, row := range rows[1:] {
		lineNumber := index + 2
		if len(row) == 1 && strings.TrimSpace(row[0]) == "" {
			continue
		}
		if len(row) != 2 {
			return nil, fmt.Errorf("строка %d: ожидалось 2 колонки, получено %d", lineNumber, len(row))
		}
		score, convErr := strconv.Atoi(strings.TrimSpace(row[1]))
		if convErr != nil {
			return nil, fmt.Errorf("строка %d: неверный балл %q", lineNumber, row[1])
		}
		records = append(records, Record{Name: strings.TrimSpace(row[0]), Score: score})
	}
	return records, nil
}

// AverageScore считает средний балл.
func AverageScore(records []Record) float64 {
	if len(records) == 0 {
		return 0
	}
	total := 0
	for _, record := range records {
		total += record.Score
	}
	return float64(total) / float64(len(records))
}

func main() {
	records, _ := ParseCSV("name,score\nАня,90\nБорис,80\n")
	fmt.Println(AverageScore(records))
}

