exercises.solution:
package main

import "fmt"

// Map применяет convert к каждому элементу.
func Map[T, R any](items []T, convert func(T) R) []R {
	result := make([]R, 0, len(items))
	for _, item := range items {
		result = append(result, convert(item))
	}
	return result
}

// Filter оставляет элементы, для которых keep вернул true.
func Filter[T any](items []T, keep func(T) bool) []T {
	result := make([]T, 0, len(items))
	for _, item := range items {
		if keep(item) {
			result = append(result, item)
		}
	}
	return result
}

// Reduce сворачивает срез в одно значение.
func Reduce[T, A any](items []T, initial A, combine func(A, T) A) A {
	accumulator := initial
	for _, item := range items {
		accumulator = combine(accumulator, item)
	}
	return accumulator
}

// Unique убирает повторы, сохраняя порядок.
func Unique[T comparable](items []T) []T {
	seen := make(map[T]bool, len(items))
	result := make([]T, 0, len(items))
	for _, item := range items {
		if seen[item] {
			continue
		}
		seen[item] = true
		result = append(result, item)
	}
	return result
}

func main() {
	fmt.Println(Map([]int{1, 2, 3}, func(value int) int { return value * 2 }))
}

