package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"sync"
)

// Task — задача в списке.
type Task struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu     sync.Mutex
	tasks  []Task
	nextID int
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(body)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

func (s *store) find(id int) int {
	for index, task := range s.tasks {
		if task.ID == id {
			return index
		}
	}
	return -1
}

// NewAPI собирает HTTP-обработчик со списком задач в памяти.
func NewAPI() http.Handler {
	mux := http.NewServeMux()
	s := &store{nextID: 1}

	mux.HandleFunc("GET /tasks", func(w http.ResponseWriter, r *http.Request) {
		s.mu.Lock()
		defer s.mu.Unlock()
		writeJSON(w, http.StatusOK, map[string]any{"tasks": append([]Task{}, s.tasks...)})
	})

	mux.HandleFunc("POST /tasks", func(w http.ResponseWriter, r *http.Request) {
		var payload struct {
			Title string `json:"title"`
		}
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			writeError(w, http.StatusBadRequest, "invalid json")
			return
		}
		if payload.Title == "" {
			writeError(w, http.StatusBadRequest, "title is required")
			return
		}
		s.mu.Lock()
		task := Task{ID: s.nextID, Title: payload.Title}
		s.nextID++
		s.tasks = append(s.tasks, task)
		s.mu.Unlock()
		writeJSON(w, http.StatusCreated, task)
	})

	mux.HandleFunc("PATCH /tasks/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(r.PathValue("id"))
		if err != nil {
			writeError(w, http.StatusNotFound, "task not found")
			return
		}
		s.mu.Lock()
		index := s.find(id)
		if index < 0 {
			s.mu.Unlock()
			writeError(w, http.StatusNotFound, "task not found")
			return
		}
		s.tasks[index].Done = true
		task := s.tasks[index]
		s.mu.Unlock()
		writeJSON(w, http.StatusOK, task)
	})

	mux.HandleFunc("DELETE /tasks/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(r.PathValue("id"))
		if err != nil {
			writeError(w, http.StatusNotFound, "task not found")
			return
		}
		s.mu.Lock()
		index := s.find(id)
		if index < 0 {
			s.mu.Unlock()
			writeError(w, http.StatusNotFound, "task not found")
			return
		}
		s.tasks = append(s.tasks[:index], s.tasks[index+1:]...)
		s.mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	})

	return mux
}

func main() {
	http.ListenAndServe(":8080", NewAPI())
}

