	"net/http/httptest"
	"strings"
	"testing"
)

func do(t *testing.T, handler http.Handler, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	var reader *strings.Reader
	if body == "" {
		reader = strings.NewReader("")
	} else {
		reader = strings.NewReader(body)
	}
	request := httptest.NewRequest(method, path, reader)
	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, request)
	return recorder
}

// TestAPICreateAndList создаёт задачу и читает список.
func TestAPICreateAndList(t *testing.T) {
	api := NewAPI()

	created := do(t, api, http.MethodPost, "/tasks", `{"title":"Учить Go"}`)
	if created.Code != http.StatusCreated {
		t.Fatalf("POST код = %d, тело %s", created.Code, created.Body.String())
	}
	var task Task
	if err := json.NewDecoder(created.Body).Decode(&task); err != nil {
		t.Fatalf("ответ не JSON: %v", err)
	}
	if task.ID != 1 || task.Title != "Учить Go" || task.Done {
		t.Fatalf("задача = %+v", task)
	}

	list := do(t, api, http.MethodGet, "/tasks", "")
	if list.Code != http.StatusOK {
		t.Fatalf("GET код = %d", list.Code)
	}
	var body struct {
		Tasks []Task `json:"tasks"`
	}
	if err := json.NewDecoder(list.Body).Decode(&body); err != nil {
		t.Fatalf("ответ не JSON: %v", err)
	}
	if len(body.Tasks) != 1 || body.Tasks[0].Title != "Учить Go" {
		t.Fatalf("список = %+v", body.Tasks)
	}
}

// TestAPIPatchMarksDone отмечает задачу выполненной.
func TestAPIPatchMarksDone(t *testing.T) {
	api := NewAPI()
	do(t, api, http.MethodPost, "/tasks", `{"title":"Первая"}`)
	patched := do(t, api, http.MethodPatch, "/tasks/1", "")
	if patched.Code != http.StatusOK {
		t.Fatalf("PATCH код = %d", patched.Code)
	}
	var task Task
	if err := json.NewDecoder(patched.Body).Decode(&task); err != nil {
		t.Fatalf("ответ не JSON: %v", err)
	}
	if !task.Done {
		t.Fatalf("задача не выполнена: %+v", task)
	}
}

// TestAPIDelete удаляет задачу.
func TestAPIDelete(t *testing.T) {
	api := NewAPI()
	do(t, api, http.MethodPost, "/tasks", `{"title":"Удалить меня"}`)
	deleted := do(t, api, http.MethodDelete, "/tasks/1", "")
	if deleted.Code != http.StatusNoContent {
		t.Fatalf("DELETE код = %d", deleted.Code)
	}
	list := do(t, api, http.MethodGet, "/tasks", "")
	var body struct {
		Tasks []Task `json:"tasks"`
	}
	json.NewDecoder(list.Body).Decode(&body)
	if len(body.Tasks) != 0 {
		t.Fatalf("список после удаления = %+v", body.Tasks)
	}
}

// TestAPINotFound возвращает 404 для неизвестного id.
func TestAPINotFound(t *testing.T) {
	api := NewAPI()
	for _, response := range []*httptest.ResponseRecorder{
		do(t, api, http.MethodPatch, "/tasks/99", ""),
		do(t, api, http.MethodDelete, "/tasks/99", ""),
	} {
		if response.Code != http.StatusNotFound {
			t.Fatalf("код = %d, ожидалось 404", response.Code)
		}
		if !strings.Contains(response.Body.String(), "task not found") {
			t.Fatalf("тело = %s", response.Body.String())
		}
	}
}

// TestAPIRejectsEmptyTitle возвращает 400 без названия.
func TestAPIRejectsEmptyTitle(t *testing.T) {
	api := NewAPI()
	response := do(t, api, http.MethodPost, "/tasks", `{"title":""}`)
	if response.Code != http.StatusBadRequest {
		t.Fatalf("код = %d, ожидалось 400", response.Code)
	}
	if !strings.Contains(response.Body.String(), "title is required") {
		t.Fatalf("тело = %s", response.Body.String())
	}
}

// TestAPIIDsIncrease выдаёт возрастающие идентификаторы.
func TestAPIIDsIncrease(t *testing.T) {
	api := NewAPI()
	first := do(t, api, http.MethodPost, "/tasks", `{"title":"a"}`)
	second := do(t, api, http.MethodPost, "/tasks", `{"title":"b"}`)
	var taskA, taskB Task
	json.NewDecoder(first.Body).Decode(&taskA)
	json.NewDecoder(second.Body).Decode(&taskB)
	if taskB.ID != taskA.ID+1 {
		t.Fatalf("id = %d и %d", taskA.ID, taskB.ID)
	}
}
